Decimal d = Decimal.valueOf('12.50');
System.assertEquals(12, d.round(RoundingMode.HALF_DOWN));
System.assertEquals(2, d.scale());
System.assertEquals(12.5, d.stripTrailingZeros());
System.assertEquals(1, d.stripTrailingZeros().scale());
System.assertEquals(12.50, d.setScale(2));
System.assertEquals(12.5, d.setScale(1, RoundingMode.HALF_UP));
System.assertEquals('12.50', d.toPlainString());
System.assertEquals(12.5, Decimal.valueOf(12.5));
System.assertEquals(9001, Decimal.valueOf(9001L));

